import { __decorate } from "tslib";
import { Component } from '@angular/core';
let FuncionariosComponent = class FuncionariosComponent {
    constructor(funcionarioService, fb, dialog) {
        this.funcionarioService = funcionarioService;
        this.fb = fb;
        this.dialog = dialog;
        this.displayedColumns = ['nome', 'id'];
        this.dataSource = [];
        this.formSearch = this.fb.group({
            search: ['', [Validators.required]],
            submit: ['']
        });
    }
    async ngOnInit() {
        this.dataSource = await this.funcionarioService.findAll();
        console.log('data:', this.dataSource);
    }
    openCreateFuncionarioDialog() {
        this.dialog.open(CreateFuncionarioFormComponent, {
            width: '400px',
            height: '400px',
        });
    }
};
FuncionariosComponent = __decorate([
    Component({
        selector: 'app-funcionarios',
        templateUrl: './funcionarios.component.html',
        styleUrls: ['./funcionarios.component.css']
    })
], FuncionariosComponent);
export { FuncionariosComponent };
